function offerRequest(name, mode){
  const body=t(`Hallo UNA Group, ich interessiere mich für ${name} (${mode}). Bitte melden Sie sich mit den nächsten Schritten und einer passenden Offerte bei mir.`,`Zdravo UNA Group, zanima me ${name} (${mode}). Molim Vas da mi se javite sa sljedećim koracima i ponudom.`);
  return `mailto:${email}?subject=${encodeURIComponent('UNA · '+name+' · '+mode)}&body=${encodeURIComponent(body)}`;
}
