function renderExtra(page){
  if(page==='websites'){render();const stale=[...document.querySelectorAll('.footer a')].find(a=>a.getAttribute('href')?.includes('page=more'));if(stale){stale.textContent=t('Automatisierungen','Automatizacije');stale.href=unaUrl('automations');}return;}
  if(page==='automations'){renderAutomations();return;}
  if(page==='offers'){renderOffers();return;}
  if(page==='training'){renderTraining();return;}
  if(page==='bridge'){renderBridge();return;}
  if(page==='solutions'){renderSolutions();return;}
  if(page==='perspective'){renderPerspective();return;}
  if(page==='log'){renderLog();return;}
  if(page==='contact'){renderContact();return;}
  if(page==='imprint'){renderImprint();return;}
  if(page==='privacy'){renderPrivacy();return;}
  renderHome();
}

function renderSolutions(){
  document.documentElement.lang=lang;
  document.title='UNA — Eigene Lösungen';
  const tools=['ChatGPT, Copilot oder Claude · für Schreiben, Recherche und Wissensarbeit','Supabase · wenn Daten sauber, sicher und an einem Ort liegen müssen','GitHub · wenn eigene Software und Änderungen sauber entwickelt werden sollen','Server & Hosting · wenn Programme stabil laufen und jemand Verantwortung übernimmt','Lokale LLMs · wenn KI im eigenen Umfeld laufen soll und Daten nicht unnötig nach außen gehen','n8n · wenn Ihre vorhandenen Programme miteinander arbeiten sollen'];
  $('#app').innerHTML=unaShell('solutions',`<section class="page-intro"><div class="eyebrow">03 · EIGENE LÖSUNGEN</div><h1>KI einführen, ohne die Leute allein damit zu lassen.</h1><p>Das Wichtigste ist nicht das modernste Tool. Das Wichtigste ist: Welches System passt zu Ihrem Unternehmen, hilft den Angestellten wirklich und bringt im Alltag einen Mehrwert?</p></section><section class="training-panel"><div><span>KI-SCHULUNGEN</span><h2>Remote per Video oder direkt vor Ort mit Ihrem Team.</h2><p>Wir wählen nicht wahllos Programme aus. Wir schauen auf Ihren Betrieb, Ihre Leute und Ihre Arbeit – dann zeigen wir Ihrem Team, welche Software für welche Aufgabe am besten passt und wie sie sicher im Arbeitsalltag eingesetzt wird.</p><a class="primary-link" href="${unaUrl('training')}">KI-Schulung ansehen</a></div><div class="training-points"><p><strong>1. Verstehen</strong> Was soll einfacher, schneller oder besser werden?</p><p><strong>2. Auswählen</strong> Welches System bringt dem Unternehmen und den Angestellten wirklich etwas?</p><p><strong>3. Einführen</strong> Remote-Schulung, Team-Workshop oder direkte Begleitung.</p></div></section><section class="software-list"><div class="eyebrow">MÖGLICHE BAUSTEINE – JE NACH BETRIEB</div><div class="software-grid">${tools.map((tool,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><p>${tool}</p></article>`).join('')}</div></section><section class="expertise-panel"><div class="eyebrow">WIR SCHAUEN NICHT NUR AUF DAS TOOL</div><h2>Im Team verbinden wir Erfahrung aus Kundenservice, Webentwicklung und Beratung rund um BWL.</h2><p>Deshalb geht es nicht nur darum, welches Programm modern aussieht. Es geht darum, ob es beim Kundenservice hilft, ob es ins Geschäft passt, ob die Mitarbeiter damit arbeiten können und ob es sich am Ende wirklich lohnt.</p></section><section class="page-cta"><h2>Sie müssen nicht alles über KI wissen.</h2><p>Sie müssen nur sagen, wo es bei Ihnen Zeit kostet, nervt oder hängen bleibt. Den Rest schauen wir mit Ihnen an.</p>${contactLinks('KI-Einführung und Schulung')}</section>`);
  bindHeader();
}

