function renderLog(){
  const posts=[
    ['Kundenservice ist kein Gesprächsproblem.','Wenn ein Kunde dreimal anrufen muss, ist nicht die Begrüßung falsch. Dann stimmt der Ablauf dahinter nicht.','Korisnička podrška nije problem razgovora.','Ako klijent mora zvati tri puta, nije problem u pozdravu. Problem je u procesu iza toga.'],
    ['Ein längeres Gespräch kann die billigere Lösung sein.','Wenn ein Mitarbeiter ein Problem richtig löst, spart er vielleicht fünf weitere Gespräche. Eine Kennzahl, die nur Zeit misst, sieht das nicht.','Duži razgovor ponekad je jeftinije rješenje.','Kada zaposlenik ispravno riješi problem, možda uštedi još pet razgovora. Mjera koja gleda samo vrijeme to ne vidi.'],
    ['Nicht alles, was digital aussieht, ist auch besser organisiert.','Man kann Zettelwirtschaft digitalisieren und trotzdem jeden Tag dieselbe Arbeit doppelt machen.','Nije sve što izgleda digitalno bolje organizovano.','Možete digitalizovati papirnu administraciju i ipak svaki dan raditi isti posao dvaput.'],
    ['Vertrauen ist vor der Technik da.','Ein Unternehmer gibt nicht einfach Kontrolle ab. Er muss zuerst sehen, dass jemand versteht, was in seinem Betrieb wirklich passiert.','Povjerenje dolazi prije tehnologije.','Poduzetnik ne predaje kontrolu olako. Prvo mora vidjeti da neko razumije šta se stvarno dešava u njegovoj firmi.']
  ];
  document.documentElement.lang=lang;document.title=t('UNA — Logbuch','UNA — Bilješke');
  $('#app').innerHTML=unaShell('log',`<section class="page-intro"><div class="eyebrow">05 · ${t('LOGBUCH','BILJEŠKE')}</div><h1>${t('Dinge, die sonst zwischen den Abteilungen verschwinden.','Stvari koje inače nestanu između odjela.')}</h1><p>${t('Hier kommen Gedanken, Beobachtungen und Dinge hinein, die ich aus der Arbeit, aus Gesprächen und aus dem Alltag sehe.','Ovdje dolaze misli, opažanja i stvari koje vidim iz rada, razgovora i svakodnevice.')}</p></section><section class="log-list">${posts.map((post,i)=>`<article><span>${String(i+1).padStart(2,'0')} · 2026</span><h2>${t(post[0],post[2])}</h2><p>${t(post[1],post[3])}</p></article>`).join('')}</section>`);bindHeader();
}
